/* MODUL SERVER 1.8.7 — untuk kernel Code.gs v2.5 (kumulatif dari 1.0.0 … 1.8.6) · 1.8.7: data gudang dibaca per halaman (gudangBacaHal) · 1.8.6: pembacaan bundel tahan jawaban AI terpotong/bukan JSON · 1.8.5: PDF unggahan manual checklist diutamakan atas bundel pada Verifikasi Tagihan · L) Asisten AI multi-penyedia & agen · N) Verifikasi Tagihan (AI auditor, bundel PDF, gerbang bayar — menu Keuangan & Bayar) · T) Tim AI Proyek (agen terjadwal: verifikasi, analisis, laporan & saran) · K/L/N butuh Code.gs 2.5.1
 * Isi: B) Arsip Dokumen Vendor (+ Akta Pendirian, Akta Perubahan, Jaminan Pelaksanaan) · E) Pembatas login 5x / 5 menit · F) Manifest SHA-256 PDF
 *      · G) Gudang: Penerimaan (per Bon, kiriman bertahap) & Pengeluaran Material · H) Diagnostik server · I) Identitas Pelaksana (KSO / Non-KSO) · J) Impor Migrasi Gudang (Admin).
 * ADITIF: sheet baru <ID>_ArsipVendor & <ID>_ManifestBerkas; tidak mengubah sheet/kolom/data lama; tanpa izin Google baru.
 * Memakai fungsi inti kernel (s_, sheet_, baris_, ss_, catat_, tglValid_, idBaru_, cl217RefValid_, folderProyek_, ...). */

/* ---------- E. Pembatas login ---------- */
const RL_MAKS = 5, RL_JEDA = 300, RL_TTL = 900;
const rlKunci = nama => 'RL246_' + s_(nama).trim().toLowerCase().slice(0, 80);
function rlBaca(nama) { try { return JSON.parse(CacheService.getScriptCache().get(rlKunci(nama)) || 'null'); } catch (e) { return null; } }
function rlCek(nama) {
  const r = rlBaca(nama); if (!r || !r.sampai) return;
  const sisa = Math.ceil((Number(r.sampai) - Date.now()) / 1000);
  if (sisa > 0) throw new Error('Akun dikunci sementara karena ' + RL_MAKS + ' kali gagal masuk. Coba lagi dalam ' + Math.floor(sisa / 60) + ' menit ' + (sisa % 60) + ' detik, atau minta Admin membuka kunci. [TERKUNCI:' + sisa + ']');
}
function rlGagal(nama, proyek) {
  if (!s_(nama).trim()) return;
  let r = rlBaca(nama) || { n: 0 };
  if (r.sampai && Number(r.sampai) <= Date.now()) r = { n: 0 };
  r.n = (Number(r.n) || 0) + 1; r.akhir = Date.now();
  if (r.n >= RL_MAKS) {
    r.sampai = Date.now() + RL_JEDA * 1000;
    try { const P = s_(proyek || PROYEK_AWAL.id); if (semuaProyek_().some(p => p.id === P)) catat_(P, { id: 'LOGIN', noKontrak: s_(nama).slice(0, 60) }, { nama: s_(nama).slice(0, 60), peran: '-' }, 'LOGIN DIKUNCI', RL_MAKS + 'x gagal masuk · jeda ' + (RL_JEDA / 60) + ' menit'); } catch (e) { }
  }
  try { CacheService.getScriptCache().put(rlKunci(nama), JSON.stringify(r), RL_TTL); } catch (e) { }
  if (r.sampai) rlCek(nama);
  const sisa = RL_MAKS - r.n;
  if (sisa > 0 && sisa <= 2) throw new Error('Nama atau kata sandi salah. Sisa ' + sisa + ' kali percobaan sebelum akun dikunci 5 menit.');
}
function rlBerhasil(nama) { try { const c = CacheService.getScriptCache(), k = rlKunci(nama); if (c.get(k)) c.remove(k); } catch (e) { } }

/* ---------- F. Manifest SHA-256 ---------- */
const MF_COL = ['Waktu', 'ID Berkas', 'Nama Berkas', 'Ukuran', 'SHA-256', 'Oleh', 'Jenis', 'Keterangan', 'Sumber'];
const hex = bytes => Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, bytes).map(b => ('0' + (b & 255).toString(16)).slice(-2)).join('');
function mfCatat(P, f, bytes, u, now, jenis, ket, sumber) {
  const h = hex(bytes);
  sheet_(P + '_ManifestBerkas', MF_COL).appendRow([now, f.getId(), s_(f.getName()).slice(0, 300), bytes.length, h, s_(u.nama), s_(jenis).slice(0, 60), s_(ket).slice(0, 300), sumber || 'unggah']);
  return h;
}
function mfBaca(P) {
  const sh = ss_().getSheetByName(P + '_ManifestBerkas'); if (!sh) return [];
  return baris_(sh).filter(r => s_(r[1])).map(r => ({ waktu: r[0] instanceof Date ? r[0].toISOString() : s_(r[0]), id: s_(r[1]), nama: s_(r[2]), ukuran: Number(r[3]) || 0,
    sha256: s_(r[4]), oleh: s_(r[5]), jenis: s_(r[6]), ket: s_(r[7]), sumber: s_(r[8]) || 'unggah' }));
}

/* ---------- B. Arsip Dokumen Vendor ---------- */
const AV_COL = ['ID', 'Kode Vendor', 'Nama Vendor', 'Jenis', 'No Dokumen', 'Berlaku s.d.', 'Status', 'Diubah Oleh', 'Diubah Pada', 'DATA'];
const AV_JENIS = ['KTP', 'NPWP', 'SBUJK', 'SIUP', 'NIB', 'JUM', 'BG', 'ASURANSI', 'AKTA_PENDIRIAN', 'AKTA_PERUBAHAN', 'JAMPEL'];
const AV_WAJIB_TGL = ['JUM', 'BG', 'ASURANSI', 'JAMPEL'];
function avBaca(P) { const sh = ss_().getSheetByName(P + '_ArsipVendor'); return sh ? baris_(sh).filter(r => r[9]).map(r => JSON.parse(s_(r[9]))) : []; }
function avTulis(P, rec, baru) {
  const sh = sheet_(P + '_ArsipVendor', AV_COL), vals = [rec.id, "'" + rec.kodeVendor, rec.namaVendor, rec.jenis, rec.noDok, rec.berlakuSd, rec.status, rec.diubahOleh, rec.diubahPada, JSON.stringify(rec)];
  if (baru) { sh.appendRow(vals); return; }
  const i = baris_(sh).findIndex(r => s_(r[0]) === rec.id); if (i < 0) throw new Error('Dokumen arsip tidak ditemukan.');
  sh.getRange(i + 2, 1, 1, vals.length).setValues([vals]);
}
function avSimpan(P, x, u, now) {
  if (u.peran !== 'PENGADAAN') throw new Error('Hanya Pengadaan atau Admin yang dapat mengisi arsip dokumen vendor.');
  const jenis = s_(x.jenis).toUpperCase(); if (AV_JENIS.indexOf(jenis) < 0) throw new Error('Jenis dokumen arsip tidak dikenal.');
  const kode = s_(x.kodeVendor).trim().slice(0, 60), nama = s_(x.namaVendor).trim().slice(0, 200); if (!kode || !nama) throw new Error('Vendor wajib dipilih.');
  const berlakuSd = tglValid_(x.berlakuSd), tglTerbit = tglValid_(x.tglTerbit);
  if (AV_WAJIB_TGL.indexOf(jenis) >= 0 && !berlakuSd) throw new Error('Tanggal berlaku s.d. wajib diisi untuk Jaminan Uang Muka / Jaminan Pelaksanaan / Bank Garansi / Asuransi.');
  const file = cl217RefValid_(P, x.file), L = avBaca(P);
  let lama = null;
  if (x.gantiId) {
    lama = L.find(r => r.id === s_(x.gantiId)); if (!lama) throw new Error('Dokumen yang akan diganti tidak ditemukan.');
    if (lama.status !== 'AKTIF') throw new Error('Dokumen ini sudah tidak aktif (diganti/dicabut). Muat ulang.');
    if (Number(x.versi) !== Number(lama.versi)) throw new Error('KONFLIK: dokumen arsip sudah diubah oleh ' + lama.diubahOleh + '. Muat ulang.');
  }
  let sha = ''; try { const m = mfBaca(P).filter(r => r.id === file.idServer).pop(); if (m) sha = m.sha256; } catch (e) { }
  const rec = { id: idBaru_('AV'), kodeVendor: kode, namaVendor: nama, jenis: jenis, noDok: s_(x.noDok).trim().slice(0, 80), tglTerbit: tglTerbit, berlakuSd: berlakuSd,
    noKontrak: s_(x.noKontrak).trim().slice(0, 120), ket: s_(x.ket).trim().slice(0, 300), file: file, sha256: sha, status: 'AKTIF', versi: 1,
    dibuatOleh: u.nama, dibuatPada: now, diubahOleh: u.nama, diubahPada: now, mengganti: lama ? lama.id : '' };
  avTulis(P, rec, true);
  if (lama) { Object.assign(lama, { status: 'DIGANTI', digantiOleh: rec.id, diubahOleh: u.nama, diubahPada: now, versi: Number(lama.versi) + 1 }); avTulis(P, lama, false); }
  catat_(P, { id: rec.id, noKontrak: rec.noKontrak || kode }, u, lama ? 'GANTI ARSIP VENDOR' : 'TAMBAH ARSIP VENDOR', nama + ' · ' + jenis + (rec.noDok ? ' · ' + rec.noDok : '') + (berlakuSd ? ' · berlaku s.d. ' + berlakuSd : '') + ' · ' + file.nama);
  return { ok: true, data: rec, diganti: lama };
}
function avCabut(P, x, u, now) {
  if (u.peran !== 'PENGADAAN') throw new Error('Hanya Pengadaan atau Admin yang dapat mencabut dokumen arsip.');
  const alasan = s_(x.alasan).trim(); if (alasan.length < 12) throw new Error('Alasan pencabutan minimal 12 karakter.');
  const lama = avBaca(P).find(r => r.id === s_(x.id));
  if (!lama) throw new Error('Dokumen arsip tidak ditemukan.');
  if (lama.status !== 'AKTIF') throw new Error('Dokumen ini sudah tidak aktif.');
  if (Number(x.versi) !== Number(lama.versi)) throw new Error('KONFLIK: dokumen arsip sudah diubah oleh ' + lama.diubahOleh + '. Muat ulang.');
  Object.assign(lama, { status: 'DICABUT', alasanCabut: alasan.slice(0, 300), diubahOleh: u.nama, diubahPada: now, versi: Number(lama.versi) + 1 });
  avTulis(P, lama, false);
  catat_(P, { id: lama.id, noKontrak: lama.noKontrak || lama.kodeVendor }, u, 'CABUT ARSIP VENDOR', lama.namaVendor + ' · ' + lama.jenis + ' · alasan: ' + alasan.slice(0, 200) + ' (berkas PDF tetap tersimpan)');
  return { ok: true, data: lama };
}


/* ---------- G. Gudang (1.1.0): Penerimaan (GR) & Pengeluaran (GI) ----------
 * Sheet BARU <ID>_GudangMasuk & <ID>_GudangKeluar. Laporan Harian, Kartu Gudang & Stok dihitung di aplikasi dari dua sheet ini.
 * Aturan: penerimaan wajib item Bon + No./file surat jalan + minimal 1 foto; qty ≤ sisa bon; pengeluaran ≤ stok (saldo tidak boleh minus
 * pada tanggal mana pun) + penerima + 1 foto serah terima. Koreksi = BATAL beralasan (baris tidak dihapus). */
const GD_MASUK_COL = ['ID', 'Tanggal', 'No Bon', 'Baris Bon', 'Kode Material', 'Uraian', 'Satuan', 'Qty', 'Harga', 'No Surat Jalan', 'Diterima Oleh', 'Status', 'Diubah Oleh', 'Diubah Pada', 'DATA'];
const GD_KELUAR_COL = ['ID', 'Tanggal', 'Kode Material', 'Uraian', 'Satuan', 'Qty', 'Untuk', 'Penerima', 'Status', 'Diubah Oleh', 'Diubah Pada', 'DATA'];
const GD_SISI = ['Tampak Depan', 'Tampak Belakang', 'Samping Kanan', 'Samping Kiri'];
const GD_FOTO_MAKS = 3 * 1024 * 1024;
const gdKunci = (kode, uraian, sat) => { const k = s_(kode).trim(); return k ? k : 'U:' + s_(uraian).trim().toUpperCase().replace(/\s+/g, ' ') + '|' + s_(sat).trim().toUpperCase(); };
const gdNamaSheet = (P, j) => P + (j === 'masuk' ? '_GudangMasuk' : '_GudangKeluar');
function gdBaca(P, j) {
  const sh = ss_().getSheetByName(gdNamaSheet(P, j)); if (!sh) return [];
  const iD = (j === 'masuk' ? GD_MASUK_COL : GD_KELUAR_COL).length - 1;
  return baris_(sh).filter(r => r[iD]).map(r => { try { return JSON.parse(s_(r[iD])); } catch (e) { return null; } }).filter(Boolean);
}
// 1.8.7: baca transaksi gudang PER HALAMAN — hanya kolom DATA pada rentang baris, respons kecil walau data gudang besar (gudangBaca utuh tetap ada)
function gdBacaHal(P, j, mulai, batas) {
  if (['masuk', 'keluar'].indexOf(j) < 0) throw new Error('Jenis transaksi gudang tidak dikenal.');
  const sh = ss_().getSheetByName(gdNamaSheet(P, j)), total = sh ? Math.max(0, sh.getLastRow() - 1) : 0;
  mulai = Math.max(0, Math.floor(Number(mulai) || 0)); batas = Math.min(1000, Math.max(1, Math.floor(Number(batas) || 250)));
  const n = Math.max(0, Math.min(batas, total - mulai)), kol = (j === 'masuk' ? GD_MASUK_COL : GD_KELUAR_COL).length;
  const data = n ? sh.getRange(2 + mulai, kol, n, 1).getValues().map(r => { if (!r[0]) return null; try { return JSON.parse(s_(r[0])); } catch (e) { return null; } }).filter(Boolean) : [];
  return { ok: true, versiServer: VERSI_SERVER, jenis: j, mulai: mulai, berikut: mulai + n, total: total, selesai: mulai + n >= total, data: data };
}
function gdTulis(P, j, rec, baru) {
  const masuk = j === 'masuk', sh = sheet_(gdNamaSheet(P, j), masuk ? GD_MASUK_COL : GD_KELUAR_COL);
  const vals = masuk
    ? ["'" + rec.tanggal, rec.bonNomor, rec.bonIdx + 1, "'" + rec.kode, rec.uraian, rec.sat, rec.qty, rec.harga, rec.noSJ, rec.diterimaOleh, rec.status, rec.diubahOleh, rec.diubahPada, JSON.stringify(rec)]
    : ["'" + rec.tanggal, "'" + rec.kode, rec.uraian, rec.sat, rec.qty, rec.untuk, rec.penerima, rec.status, rec.diubahOleh, rec.diubahPada, JSON.stringify(rec)];
  vals.unshift(rec.id);
  if (baru) { sh.appendRow(vals); return; }
  const i = baris_(sh).findIndex(r => s_(r[0]) === rec.id); if (i < 0) throw new Error('Data gudang tidak ditemukan.');
  sh.getRange(i + 2, 1, 1, vals.length).setValues([vals]);
}
function gdKunciTulis(fn) {   // hindari dua petugas mengambil sisa bon / stok yang sama bersamaan
  const lk = LockService.getScriptLock(), sudah = lk.hasLock();
  if (!sudah && !lk.tryLock(20000)) throw new Error('Server sedang sibuk menyimpan data gudang lain. Coba lagi beberapa detik.');
  try { return fn(); } finally { if (!sudah) lk.releaseLock(); }
}
function gdRef(P, raw, label, bolehPdf) {
  const b = refBerkas_(raw);
  if (!b || !b.idServer) throw new Error(label + ' wajib diunggah ke server (Google Drive).');
  let f; try { f = DriveApp.getFileById(b.idServer); } catch (e) { throw new Error(label + ' tidak ditemukan di Google Drive.'); }
  const pid = folderProyek_(P).getId(), it = f.getParents(); let milik = false;
  while (it.hasNext()) if (it.next().getId() === pid) milik = true;
  if (!milik) throw new Error(label + ' bukan milik proyek ' + P + '.');
  const mime = f.getMimeType(), gambar = /^image\/(jpeg|png)$/.test(mime);
  if (!(gambar || (bolehPdf && mime === 'application/pdf'))) throw new Error(label + ' harus ' + (bolehPdf ? 'PDF atau foto JPG/PNG' : 'foto JPG/PNG') + '.');
  if (f.getSize() > BATAS_PDF) throw new Error(label + ' maksimal 10 MB.');
  return { id: s_(b.id) || f.getId(), idServer: f.getId(), nama: f.getName().slice(0, 300), ukuran: f.getSize(), jenis: s_(b.jenis).slice(0, 60), lokasi: 'server', tipe: mime, url: f.getUrl() };
}
function gdTimeline(M, K) {   // null = saldo aman; selain itu {tanggal, saldo} pertama yang minus
  const ev = M.map(r => ({ t: s_(r.tanggal), q: Number(r.qty) || 0, o: 0, c: s_(r.dibuatPada) }))
    .concat(K.map(r => ({ t: s_(r.tanggal), q: -(Number(r.qty) || 0), o: 1, c: s_(r.dibuatPada) })))
    .sort((a, b) => a.t.localeCompare(b.t) || a.o - b.o || a.c.localeCompare(b.c));
  let s = 0; for (let i = 0; i < ev.length; i++) { s += ev[i].q; if (s < -1e-9) return { tanggal: ev[i].t, saldo: bulat4_(s) }; }
  return null;
}
function gdTgl(x, label) {
  const t = tglValid_(x); if (!t) throw new Error(label + ' wajib diisi.');
  if (t > hariIniISO_()) throw new Error(label + ' tidak boleh melewati hari ini.');
  return t;
}
function gdMasukSimpan(P, x, u, now) {
  if (u.peran !== 'PENGADAAN') throw new Error('Hanya Pengadaan atau Admin yang dapat mencatat penerimaan material.');
  const nomor = s_(x.bonNomor).trim(), idx = parseInt(x.bonIdx, 10);
  if (!nomor || !(idx >= 0)) throw new Error('Penerimaan wajib merujuk item Bon Permintaan. Penerimaan tanpa bon ditolak.');
  const bon = bacaKoleksi_(P, 'permintaan').find(b => b.nomor === nomor);
  if (!bon) throw new Error('Bon Permintaan ' + nomor + ' tidak ditemukan.');
  const it = (bon.items || [])[idx];
  if (!it || !(Number(it.vol) > 0)) throw new Error('Item bon tidak ditemukan atau volume bon kosong.');
  if (x.kode !== undefined && s_(x.kode).trim() !== s_(it.kode).trim()) throw new Error('Isi item bon berubah. Muat ulang lalu pilih item lagi.');
  const tgl = gdTgl(x.tanggal, 'Tanggal terima');
  if (s_(bon.tanggal) && tgl < s_(bon.tanggal).slice(0, 10)) throw new Error('Tanggal terima (' + tgl + ') lebih awal dari tanggal bon (' + s_(bon.tanggal).slice(0, 10) + ').');
  const qty = Number(x.qty); if (!(qty > 0)) throw new Error('Qty harus lebih dari 0.');
  const harga = Number(x.harga) || 0; if (harga < 0) throw new Error('Harga tidak boleh negatif.');
  const noSJ = s_(x.noSJ).trim().slice(0, 60);
  if (!noSJ) throw new Error('No. Surat Jalan wajib diisi. Semua penerimaan harus disertai surat jalan.');
  const sj = gdRef(P, x.sjFile, 'File surat jalan', true);
  const foto = (Array.isArray(x.foto) ? x.foto : []).slice(0, 4).map((f, i) => f ? Object.assign(gdRef(P, f, 'Foto ' + GD_SISI[i], false), { sisi: GD_SISI[i] }) : null);
  while (foto.length < 4) foto.push(null);
  if (!foto.some(Boolean)) throw new Error('Unggah minimal 1 foto barang.');
  return gdKunciTulis(() => {
    const aktif = gdBaca(P, 'masuk').filter(r => r.status === 'AKTIF' && r.bonNomor === nomor && Number(r.bonIdx) === idx);
    if (aktif.some(r => s_(r.noSJ).toLowerCase() === noSJ.toLowerCase())) throw new Error('Surat jalan ' + noSJ + ' sudah dicatat untuk item bon ini.');
    const sudah = aktif.reduce((a, r) => a + (Number(r.qty) || 0), 0), sisa = Number(it.vol) - sudah;
    if (qty > sisa + 1e-9) throw new Error('Qty melebihi sisa bon: volume ' + it.vol + ', sudah diterima ' + bulat4_(sudah) + ', sisa ' + bulat4_(sisa) + ' ' + s_(it.sat) + '.');
    const rec = { id: idBaru_('GR'), tanggal: tgl, bonNomor: nomor, bonIdx: idx, bonTanggal: s_(bon.tanggal).slice(0, 10), departemen: s_(bon.departemen),
      kode: s_(it.kode).trim(), uraian: s_(it.uraian).trim(), sat: s_(it.sat).trim(), kunci: gdKunci(it.kode, it.uraian, it.sat), wbs: s_(it.wbs || bon.wbs).trim(),
      qty: bulat4_(qty), harga: harga, noSJ: noSJ, sjFile: sj, foto: foto, diterimaOleh: s_(x.diterimaOleh).trim().slice(0, 80) || u.nama, ket: s_(x.ket).trim().slice(0, 500),
      status: 'AKTIF', versi: 1, dibuatOleh: u.nama, dibuatPada: now, diubahOleh: u.nama, diubahPada: now };
    gdTulis(P, 'masuk', rec, true);
    catat_(P, { id: rec.id, noKontrak: nomor }, u, 'PENERIMAAN MATERIAL', rec.uraian + ' · ' + rec.qty + ' ' + rec.sat + ' · SJ ' + noSJ + ' · ' + foto.filter(Boolean).length + ' foto · bon baris ' + (idx + 1));
    return { ok: true, data: rec };
  });
}
function gdKeluarSimpan(P, x, u, now) {
  if (u.peran !== 'PENGADAAN') throw new Error('Hanya Pengadaan atau Admin yang dapat mencatat pengeluaran material.');
  const kunci = s_(x.kunci).trim(); if (!kunci) throw new Error('Pilih material yang dikeluarkan.');
  const tgl = gdTgl(x.tanggal, 'Tanggal keluar');
  const qty = Number(x.qty); if (!(qty > 0)) throw new Error('Qty harus lebih dari 0.');
  const untuk = s_(x.untuk).trim().slice(0, 120), penerima = s_(x.penerima).trim().slice(0, 80);
  if (!untuk) throw new Error('Isi untuk / lokasi pemakaian.');
  if (!penerima) throw new Error('Isi nama penerima barang.');
  if (!x.foto) throw new Error('Unggah 1 foto serah terima.');
  const foto = gdRef(P, x.foto, 'Foto serah terima', false);
  return gdKunciTulis(() => {
    const M = gdBaca(P, 'masuk').filter(r => r.status === 'AKTIF' && r.kunci === kunci);
    if (!M.length) throw new Error('Material ini belum pernah diterima di gudang. Catat penerimaan dulu.');
    const K = gdBaca(P, 'keluar').filter(r => r.status === 'AKTIF' && r.kunci === kunci);
    const cek = gdTimeline(M, K.concat([{ tanggal: tgl, qty: qty, dibuatPada: now }]));
    if (cek) throw new Error('Ditolak: pengeluaran ini membuat stok ' + M[0].uraian + ' minus (' + cek.saldo + ' ' + M[0].sat + ' pada ' + cek.tanggal + '). Periksa penerimaan yang belum dicatat.');
    const m0 = M[M.length - 1];
    const rec = { id: idBaru_('GI'), tanggal: tgl, kunci: kunci, kode: m0.kode, uraian: m0.uraian, sat: m0.sat, qty: bulat4_(qty), untuk: untuk, penerima: penerima,
      foto: Object.assign(foto, { sisi: 'Serah terima' }), ket: s_(x.ket).trim().slice(0, 500), status: 'AKTIF', versi: 1, dibuatOleh: u.nama, dibuatPada: now, diubahOleh: u.nama, diubahPada: now };
    gdTulis(P, 'keluar', rec, true);
    catat_(P, { id: rec.id, noKontrak: rec.kode || rec.uraian }, u, 'PENGELUARAN MATERIAL', rec.uraian + ' · ' + rec.qty + ' ' + rec.sat + ' · untuk ' + untuk + ' · diterima ' + penerima);
    return { ok: true, data: rec };
  });
}
function gdBatal(P, j, x, u, now) {
  if (u.peran !== 'PENGADAAN') throw new Error('Hanya Pengadaan atau Admin yang dapat membatalkan transaksi gudang.');
  const alasan = s_(x.alasan).trim(); if (alasan.length < 12) throw new Error('Alasan pembatalan minimal 12 karakter.');
  return gdKunciTulis(() => {
