  while (foto.length < 4) foto.push(null);
  if (!foto.some(Boolean)) throw new Error('Unggah minimal 1 foto barang.');
  return gdKunciTulis(() => {
    const aktif = gdBaca(P, 'masuk').filter(r => r.status === 'AKTIF' && r.bonNomor === nomor);
    if (aktif.some(r => s_(r.noSJ).toLowerCase() === noSJ.toLowerCase())) throw new Error('Surat jalan ' + noSJ + ' sudah dicatat untuk bon ini. Satu surat jalan = satu kiriman.');
    const salah = [];
    rinci.forEach(d => {
      const sudah = aktif.filter(r => Number(r.bonIdx) === d.idx).reduce((a, r) => a + (Number(r.qty) || 0), 0), sisa = bulat4_(Number(d.it.vol) - sudah);
      if (d.qty > sisa + 1e-9) salah.push('baris ' + (d.idx + 1) + ' ' + s_(d.it.uraian).slice(0, 40) + ': diterima ' + d.qty + ' > sisa ' + sisa + ' ' + s_(d.it.sat));
