    const kid = idBaru_('KR'), ket = s_(x.ket).trim().slice(0, 500), oleh = s_(x.diterimaOleh).trim().slice(0, 80) || u.nama;
    const recs = rinci.map((d, i) => ({ id: 'GR' + kid.slice(2) + '-' + (i + 1), tanggal: tgl, bonNomor: nomor, bonIdx: d.idx, bonTanggal: tBon, departemen: s_(bon.departemen),
      kode: s_(d.it.kode).trim(), uraian: s_(d.it.uraian).trim(), sat: s_(d.it.sat).trim(), kunci: gdKunci(d.it.kode, d.it.uraian, d.it.sat), wbs: s_(d.it.wbs || bon.wbs).trim(),
      qty: d.qty, harga: d.harga, noSJ: noSJ, sjFile: sj, foto: foto, diterimaOleh: oleh, ket: ket, kiriman: kid, kirimanKe: ke,
      status: 'AKTIF', versi: 1, dibuatOleh: u.nama, dibuatPada: now, diubahOleh: u.nama, diubahPada: now }));
    const sh = sheet_(gdNamaSheet(P, 'masuk'), GD_MASUK_COL);
    const vals = recs.map(r => [r.id, "'" + r.tanggal, r.bonNomor, r.bonIdx + 1, "'" + r.kode, r.uraian, r.sat, r.qty, r.harga, r.noSJ, r.diterimaOleh, r.status, r.diubahOleh, r.diubahPada, JSON.stringify(r)]);
    sh.getRange(sh.getLastRow() + 1, 1, vals.length, GD_MASUK_COL.length).setValues(vals);
    const sisaTotal = (bon.items || []).reduce((a, it, i) => { if (!(Number(it.vol) > 0)) return a;
      const t = aktif.concat(recs).filter(r => Number(r.bonIdx) === i).reduce((s, r) => s + (Number(r.qty) || 0), 0); return a + (Number(it.vol) - t > 1e-9 ? 1 : 0); }, 0);
    catat_(P, { id: kid, noKontrak: nomor }, u, 'PENERIMAAN MATERIAL', 'Kiriman ke-' + ke + ' · SJ ' + noSJ + ' · ' + recs.length + ' item · ' + foto.filter(Boolean).length + ' foto · ' + (sisaTotal ? sisaTotal + ' item bon masih menunggu' : 'bon diterima lengkap'));
