      if (cek) throw new Error('Kiriman tidak dapat dibatalkan: ' + kena.find(r => r.kunci === k).uraian + ' sudah dikeluarkan sehingga stok minus pada ' + cek.tanggal + '. Batalkan pengeluaran terkait dulu.');
