}

/* ---------- I. Identitas Pelaksana (1.2.0): KSO / Non-KSO per proyek ----------
 * Sheet BARU _IdentitasPelaksana (1 baris per ID proyek). Dipakai dashboard, kop cetak & login. Hanya ADMIN yang mengubah. */
const IP_COL = ['Proyek', 'Bentuk', 'Nama Pelaksana', 'Diubah Oleh', 'Diubah Pada', 'DATA'];
function ipBaca(P) {
  const sh = ss_().getSheetByName('_IdentitasPelaksana'); if (!sh) return null;
  const r = baris_(sh).find(x => s_(x[0]) === P); if (!r) return null;
  try { return JSON.parse(s_(r[5])); } catch (e) { return null; }
}
function ipSimpan(P, x, u, now) {
  if (!u.admin) throw new Error('Hanya ADMIN yang boleh mengubah identitas pelaksana proyek.');
  const bentuk = s_(x.bentuk).toUpperCase() === 'KSO' ? 'KSO' : 'TUNGGAL';
  const t = (v, n) => s_(v).replace(/\s+/g, ' ').trim().slice(0, n);
