  } else anggota = anggota.slice(0, 1).map(a => Object.assign(a, { leader: true, porsi: 100 }));
  const rec = { proyek: P, bentuk: bentuk, nama: nama, singkatan: t(x.singkatan, 6).toUpperCase() || nama.replace(/^PT\.?\s+/i, '').charAt(0).toUpperCase(),
    perusahaan: t(x.perusahaan, 120), unit: t(x.unit, 120), anggota: anggota, kodeSurat: t(x.kodeSurat, 60), diubahOleh: u.nama, diubahPada: now };
  return gdKunciTulis(() => {
    const sh = sheet_('_IdentitasPelaksana', IP_COL), L = baris_(sh), i = L.findIndex(r => s_(r[0]) === P);
    const vals = [P, bentuk, nama, u.nama, now, JSON.stringify(rec)];
    if (i < 0) sh.appendRow(vals); else sh.getRange(i + 2, 1, 1, vals.length).setValues([vals]);
    catat_(P, { id: 'IDENTITAS', noKontrak: P }, u, 'UBAH IDENTITAS PELAKSANA', bentuk + ' · ' + nama + (anggota.length ? ' · ' + anggota.map(a => a.nama + (a.porsi ? ' ' + a.porsi + '%' : '') + (a.leader ? ' (leader)' : '')).join(', ') : ''));
    return { ok: true, data: rec };
  });
}


/* ---------- J. Migrasi data gudang (1.3.0) ----------
 * Impor riwayat gudang lama (mis. WSKT Smart Warehouse LOGINV-08) dari file .json berformat "monitoring-pengadaan-migrasi-gudang".
 * KHUSUS ADMIN. Aditif & idempoten: ID yang sudah ada dilewati. Atomik: divalidasi seluruhnya dulu (termasuk stok tidak boleh minus
 * pada tanggal mana pun), baru ditulis sekaligus. Hanya ID berawalan GR-MIG- / GI-MIG-. Field direkonstruksi ulang di server (tidak percaya isi file). */
const MIG_FORMAT = 'monitoring-pengadaan-migrasi-gudang', MIG_MAKS = 5000;
