function migRek(j, x, i, u, now, P) {
  const L = (j === 'masuk' ? 'GR' : 'GI') + ' baris ' + (i + 1) + ': ';
  if (!x || typeof x !== 'object') throw new Error(L + 'isi tidak valid.');
  const id = s_(x.id).trim(); if (!MIG_ID[j].test(id)) throw new Error(L + 'ID harus berawalan ' + (j === 'masuk' ? 'GR-MIG-' : 'GI-MIG-') + ' (ditemukan "' + id.slice(0, 40) + '").');
  let tgl; try { tgl = tglValid_(x.tanggal); } catch (e) { throw new Error(L + e.message); }
  if (!tgl) throw new Error(L + 'tanggal kosong.');
  if (tgl > hariIniISO_()) throw new Error(L + 'tanggal ' + tgl + ' melewati hari ini.');
  const kode = migT(x.kode, 40), uraian = migT(x.uraian, 200), sat = migT(x.sat, 20);
  if (!uraian) throw new Error(L + 'uraian material kosong.');
  if (!sat) throw new Error(L + 'satuan kosong.');
  const qty = bulat4_(Number(x.qty)); if (!(qty > 0) || !isFinite(qty)) throw new Error(L + 'qty harus lebih dari 0.');
  const dp = /^\d{4}-\d{2}-\d{2}T[\d:.]+Z$/.test(s_(x.dibuatPada)) ? s_(x.dibuatPada) : now;
  const dasar = { id: id, tanggal: tgl, kode: kode, uraian: uraian, sat: sat, kunci: gdKunci(kode, uraian, sat), qty: qty, ket: migT(x.ket, 500),
    migrasi: true, sumberMigrasi: 'impor-json', status: 'AKTIF', versi: 1, dibuatOleh: u.nama, dibuatPada: dp, diubahOleh: u.nama, diubahPada: now, diimporOleh: u.nama, diimporPada: now };
  if (j === 'keluar') return Object.assign(dasar, { untuk: migT(x.untuk, 120) || 'Migrasi data gudang lama', penerima: migT(x.penerima, 80) || '(data lama)', foto: null });
  const harga = Number(x.harga) || 0; if (harga < 0 || !isFinite(harga)) throw new Error(L + 'harga tidak valid.');
  const bon = migT(x.bonNomor, 80) || 'MIGRASI/' + P;
  return Object.assign(dasar, { bonNomor: /^MIGRASI\//.test(bon) ? bon : 'MIGRASI/' + bon, bonIdx: Math.max(0, parseInt(x.bonIdx, 10) || 0), bonTanggal: tglValid_(x.bonTanggal) || '',
    departemen: 'MIGRASI', wbs: migT(x.wbs, 60), harga: harga, noSJ: migT(x.noSJ, 60) || 'MIGRASI', sjFile: null, foto: [null, null, null, null],
    diterimaOleh: migT(x.diterimaOleh, 80) || u.nama, kiriman: migT(x.kiriman, 40), kirimanKe: Math.max(0, parseInt(x.kirimanKe, 10) || 0),
    vendor: migT(x.vendor, 200), noKontrak: migT(x.noKontrak, 300) });
}
function migPeriksa(P, d, u, now) {
  if (!u.admin) throw new Error('Impor migrasi gudang khusus Admin.');
  if (!d || d.format !== MIG_FORMAT) throw new Error('Format file bukan "' + MIG_FORMAT + '".');
  if (s_(d.proyek) !== P) throw new Error('File migrasi untuk proyek ' + s_(d.proyek) + ', sedangkan Anda masuk ke proyek ' + P + '.');
  const IM = Array.isArray(d.masuk) ? d.masuk : [], IK = Array.isArray(d.keluar) ? d.keluar : [];
  if (!IM.length && !IK.length) throw new Error('File migrasi tidak berisi transaksi.');
  if (IM.length + IK.length > MIG_MAKS) throw new Error('Maksimal ' + MIG_MAKS + ' transaksi per impor.');
  const M0 = gdBaca(P, 'masuk'), K0 = gdBaca(P, 'keluar');
  const ada = new Set(M0.map(r => r.id).concat(K0.map(r => r.id))), lihat = new Set();
  const pilah = (L, j) => { const baru = []; let lewat = 0;
    L.forEach((x, i) => { const r = migRek(j, x, i, u, now, P);
      if (lihat.has(r.id)) throw new Error('ID ganda di file: ' + r.id); lihat.add(r.id);
      if (ada.has(r.id)) lewat++; else baru.push(r); });
    return { baru: baru, lewat: lewat }; };
  const m = pilah(IM, 'masuk'), k = pilah(IK, 'keluar');
  const MA = M0.filter(r => r.status === 'AKTIF').concat(m.baru), KA = K0.filter(r => r.status === 'AKTIF').concat(k.baru);
  const kunciBaru = [...new Set(m.baru.concat(k.baru).map(r => r.kunci))], salah = [];
  kunciBaru.forEach(kc => {
