    if (Kx.length && !Mx.length) { salah.push(Kx[0].uraian + ': ada pengeluaran tanpa penerimaan'); return; }
    const c = gdTimeline(Mx, Kx); if (c) salah.push((Mx[0] || Kx[0]).uraian + ': stok minus ' + c.saldo + ' pada ' + c.tanggal);
  });
  const sum = L => bulat4_(L.reduce((a, r) => a + r.qty, 0));
  return { masuk: m.baru, keluar: k.baru, ringkas: { masukBaru: m.baru.length, masukAda: m.lewat, keluarBaru: k.baru.length, keluarAda: k.lewat,
    qtyMasuk: sum(m.baru), qtyKeluar: sum(k.baru), material: kunciBaru.length, salah: salah.slice(0, 30), jmlSalah: salah.length } };
}
function migTulis(P, j, recs) {
  if (!recs.length) return;
  const masuk = j === 'masuk', sh = sheet_(gdNamaSheet(P, j), masuk ? GD_MASUK_COL : GD_KELUAR_COL);
  const vals = recs.map(r => masuk
    ? [r.id, "'" + r.tanggal, r.bonNomor, r.bonIdx + 1, "'" + r.kode, r.uraian, r.sat, r.qty, r.harga, r.noSJ, r.diterimaOleh, r.status, r.diubahOleh, r.diubahPada, JSON.stringify(r)]
    : [r.id, "'" + r.tanggal, "'" + r.kode, r.uraian, r.sat, r.qty, r.untuk, r.penerima, r.status, r.diubahOleh, r.diubahPada, JSON.stringify(r)]);
  sh.getRange(sh.getLastRow() + 1, 1, vals.length, vals[0].length).setValues(vals);
}
function migImpor(P, d, u, now) {
  return gdKunciTulis(() => {
    const p = migPeriksa(P, d, u, now), R = p.ringkas;
