  gudangBatalKiriman: (req, u, P, now) => gdBatalKiriman(P, req.data || {}, u, now),
  gudangImporCek: (req, u, P) => { const now = new Date().toISOString(), p = migPeriksa(P, req.data || {}, u, now); return { ok: true, ringkas: p.ringkas }; },
  gudangImporMigrasi: (req, u, P, now) => migImpor(P, req.data || {}, u, now),
  gudangMigrasiBatal: (req, u, P, now) => migBatal(P, req.data || {}, u, now),
  identitasBaca: (req, u, P) => ({ ok: true, data: ipBaca(P) }),
  identitasSimpan: (req, u, P, now) => ipSimpan(P, req.data || {}, u, now),
  gudangBatal: (req, u, P, now) => { const d = req.data || {}; if (['masuk', 'keluar'].indexOf(d.jenis) < 0) throw new Error('Jenis transaksi gudang tidak dikenal.'); return gdBatal(P, d.jenis, d, u, now); },
  rlBukaKunci: (req, u, P) => {
    if (!u.admin) throw new Error('Membuka kunci login khusus Admin.');
    const t = s_((req.data || {}).nama).trim(); if (!t) throw new Error('Pilih pengguna.');
    const r = rlBaca(t); CacheService.getScriptCache().remove(rlKunci(t));
    catat_(P, { id: 'LOGIN', noKontrak: t }, u, 'BUKA KUNCI LOGIN', r && r.sampai ? 'Kunci dibuka Admin' : 'Tidak sedang terkunci (penghitung direset)');
    return { ok: true, terkunci: !!(r && r.sampai && Number(r.sampai) > Date.now()) };
  },
  diagServer: (req, u, P) => {
    const ss = ss_(), n = nm => { const sh = ss.getSheetByName(nm); return sh ? Math.max(0, sh.getLastRow() - 1) : null; };
    const out = { ok: true, versiServer: VERSI_SERVER, kernel: KERNEL_VERSI, modul: modulRingkas_(), fitur: fiturSemua_(), waktu: new Date().toISOString(), proyek: P,
      sheet: { register: n(P + '_Register'), progres: n(P + '_Progres'), permintaan: n(P + '_Permintaan'), pbj: n(P + '_PBJ'), checklist: n(P + '_ChecklistTagihan'), arsipVendor: n(P + '_ArsipVendor'), manifest: n(P + '_ManifestBerkas'), gudangMasuk: n(P + '_GudangMasuk'), gudangKeluar: n(P + '_GudangKeluar'), log: n(P + '_Log') } };
    if (u.admin) out.terkunci = semuaPengguna_().map(p => ({ nama: p.nama, r: rlBaca(p.nama) })).filter(z => z.r && (z.r.n || z.r.sampai))
      .map(z => ({ nama: z.nama, gagal: Number(z.r.n) || 0, sisaDetik: z.r.sampai ? Math.max(0, Math.ceil((Number(z.r.sampai) - Date.now()) / 1000)) : 0 }));
    return out;
  }
};

